layer.css:
[data-ryt="pitch"] { color: rgb(164, 228, 252); background-color: var(--ryt-surface); border-top: 3px solid rgb(164, 228, 252); border-right: 3px solid rgb(164, 228, 252); border-bottom: 3px solid rgb(164, 228, 252); border-left: 5px solid rgb(164, 228, 252); border-radius: 0px; box-shadow: var(--ryt-surface) 3px 3px 0px 0px, rgba(124, 124, 124, 0.25) 0px 0px 0px 2px inset; font-family: var(--ryt-font-body); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(164, 228, 252); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 20px; padding-right: 20px; padding-bottom: 20px; padding-left: 20px; transition: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 3px solid var(--ryt-border); border-right: 3px solid var(--ryt-border); border-bottom: 3px solid var(--ryt-border); border-left: 3px solid var(--ryt-border); border-radius: 0px; box-shadow: var(--ryt-surface) 3px 3px 0px 0px, rgba(124, 124, 124, 0.25) 0px 0px 0px 2px inset; transition: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 3px solid var(--ryt-border); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 2px solid rgba(0, 0, 0, 0); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; transition: none; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: var(--ryt-border); font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: 1.2px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: auto; text-shadow: var(--ryt-surface) 2px 2px 0px; transition: none }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: none }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-border); border-bottom: 2px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 500; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: 4px; transition: none; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: var(--ryt-border); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 22px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: 1.1px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: 4px; text-shadow: var(--ryt-surface) 2px 2px 0px; transition: none }
[data-ryt="nav"] a { color: var(--ryt-accent); border-bottom: 2px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 20px; transition: none; border-top: none; border-right: none; border-left: none; position: relative }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-border); border-bottom: 2px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 500; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-border); text-decoration-thickness: auto; text-underline-offset: 4px; transition: none; padding-top: 23px; border-top: none; border-right: none; border-left: none; position: relative }
[data-ryt="rec-card"] [data-ryt="title"]::before { content: "▶"; display: block; position: absolute; width: 10.4062px; height: 18.7188px; color: rgb(248, 184, 0); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 10.4px; font-weight: 500; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 184, 0); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(248, 184, 0); top: 0px; left: 0px }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-color: #F87858; color: #FCA044; color: #F87858; border-bottom-color: #F87858 }
[data-ryt="nav"] a::before { content: "▶"; display: block; position: absolute; width: 10.4062px; height: 17.6875px; color: rgb(248, 184, 0); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 10.4px; font-weight: 400; font-style: normal; line-height: 1.7; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(248, 184, 0); text-decoration-thickness: auto; text-underline-offset: 4px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(248, 184, 0); top: 0px; left: 0px }
[data-ryt="nav"] a:hover { text-decoration-color: #F87858; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #F87858; border-bottom-color: #F87858; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-color: #F87858; color: #FCA044; color: #F87858; border-bottom-color: #F87858 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { text-decoration-color: #F87858; color: #F87858; border-bottom-color: #F87858 }
